/* 状态栏 wifi/bt 图标 ← 驱动实时状态（每秒由 clock timer 调用）
 * 2026-08-10 修复（-28）：开关语义——WiFi/BT 打开 → 显示蓝色符号；
 * 关闭 → 整枚隐藏（对齐 Settings 开关逻辑：开了才显示，弃"断开灰"
 * 低对比显示）。Home/子页/锁屏三处指针统一处理；隐藏后 flex 自动收拢不占位。 */
static void dm_status_icon_refresh(lv_obj_t *lbl, int on)
{
    if (!lbl) return;
    if (on) {
        lv_obj_clear_flag(lbl, LV_OBJ_FLAG_HIDDEN);
        lv_obj_set_style_text_color(lbl, lv_color_hex(COL_BLUE), 0);
    } else {
        lv_obj_add_flag(lbl, LV_OBJ_FLAG_HIDDEN);
    }
}

void dm_net_status_refresh(void)
{
    int wifi_up = dm_net_wifi_is_up();
    int bt_on   = dm_net_bt_is_on();   /* socket IPC 低频刷新在 dm_net.c 内部 */

    /* Home 状态栏 */
    dm_status_icon_refresh(status_wifi_lbl, wifi_up);
    dm_status_icon_refresh(status_bt_lbl,   bt_on);
    /* 子页状态栏（挂 overlay，关闭前置空） */
    dm_status_icon_refresh(subpage_wifi_lbl, wifi_up);
    dm_status_icon_refresh(subpage_bt_lbl,   bt_on);
    /* 锁屏状态栏（show_standby 创建） */
    dm_status_icon_refresh(standby_bar_wifi_lbl, wifi_up);
    dm_status_icon_refresh(standby_bar_bt_lbl,   bt_on);
}

