        lv_obj_set_style_text_color(standby_bar_wifi_lbl,
            up ? lv_color_hex(COL_BLUE) : lv_color_hex(COL_SEC), 0);
    }
    if (standby_bar_bt_lbl) {
        int on = dm_net_bt_is_on();
        lv_obj_set_style_text_color(standby_bar_bt_lbl,
